package org.securemail.identity;

import java.nio.file.Path;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import org.securemail.ecosystem.protocol.IdentityAdministrationProtocol600;
import static org.junit.jupiter.api.Assertions.*;

/** Real SQLite authority/replay/permit checks. No native or Tor acceptance claim. */
class IdentityAdministration600Test {
 @TempDir Path home;CriticalApprovalTest f;Capability owner,second;
 @BeforeEach void setup()throws Exception{f=new CriticalApprovalTest();f.home=home;f.setup();owner=f.admin(f.owner);second=f.admin(f.second);}
 @AfterEach void close()throws Exception{f.close();}
 byte[] proof(CriticalApprovalTest.Person p,Capability cap,byte[] body,String nonce){return IdentityProtocol.sign(p.app().getPrivate(),IdentityProtocol.requestDigest(cap,"admin.execute",IdentityProtocol.digest(body),f.clock.millis(),nonce));}
 Map<String,Object> inspect(CriticalApprovalTest.Person p,Capability cap,String id,String nonce){return f.store.inspectCritical(cap,id,f.clock.millis(),nonce,proof(p,cap,IdentityAdministrationProtocol600.criticalInspection(f.store.audience(),id,f.clock.millis(),nonce),nonce));}
 void revoke(CriticalApprovalTest.Person p,Capability cap,Map<String,Object> permit,String target){String id=(String)permit.get("requestId"),n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.criticalApproval(f.store.audience(),p.account(),"administrator.revoke",id,IdentityProtocol.administratorRevocation(target),(Long)permit.get("expiresAt"));f.store.revokeAdministrator(cap,id,target,f.clock.millis(),n,proof(p,cap,b,n));}
 void assign(Map<String,Object> permit,String target,String role){String id=(String)permit.get("requestId"),n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.criticalApproval(f.store.audience(),f.owner.account(),"administrator.assign",id,IdentityProtocol.administratorAssignment(target,role),(Long)permit.get("expiresAt"));f.store.assignAdministrator(owner,id,target,role,f.clock.millis(),n,proof(f.owner,owner,b,n));}
 @Test void inspectionReadsPersistedMetadataAndRequiresSeparateFreshProof(){byte[] payload=IdentityProtocol.administratorAssignment(f.second.account(),"Новая должность");Map<String,Object> p=f.request(f.owner,owner,"administrator.assign",payload);String id=(String)p.get("requestId"),n=IdentityProtocol.nonce();Map<String,Object> actual=inspect(f.second,second,id,n);assertEquals(Set.of("audience","initiatorAccountId","requestId","operation","payloadSha256","expiresAt"),actual.keySet());assertEquals(f.store.audience(),actual.get("audience"));assertEquals(f.owner.account(),actual.get("initiatorAccountId"));assertEquals(p.get("payloadSha256"),actual.get("payloadSha256"));assertThrows(IdentityException.class,()->inspect(f.second,second,id,n));String wrong=IdentityProtocol.nonce();byte[] approval=IdentityProtocol.criticalApproval(f.store.audience(),f.second.account(),"administrator.assign",id,payload,(Long)p.get("expiresAt"));assertThrows(IdentityException.class,()->f.store.inspectCritical(second,id,f.clock.millis(),wrong,proof(f.second,second,approval,wrong)));f.clock.value+=120001;assertThrows(IdentityException.class,()->inspect(f.second,second,id,IdentityProtocol.nonce()));}
 @Test void revokedExternalAdminRemainsRevokedAcrossReopenUntilTwoAdminAssignment()throws Exception{var third=f.register();f.delegated.add(third.account());Capability other=f.admin(third);String target=f.second.account();byte[] body=IdentityProtocol.administratorRevocation(target);Map<String,Object> p=f.request(f.owner,owner,"administrator.revoke",body);f.approve(third,other,p,body);revoke(f.owner,owner,p,target);assertFalse(f.store.isActive(second));assertEquals(false,f.store.currentAuthority(target).get("authorityAdministrator"));assertThrows(IdentityException.class,()->f.admin(f.second));f.store.close();f.store=new IdentityStore(home.resolve("identity.db"),f.service,f.audit,f.clock,f.delegated::contains);assertEquals(false,f.store.currentAuthority(target).get("authorityAdministrator"));String role="Назначен заново";body=IdentityProtocol.administratorAssignment(target,role);p=f.request(f.owner,owner,"administrator.assign",body);f.approve(third,other,p,body);assign(p,target,role);assertEquals(true,f.store.currentAuthority(target).get("authorityAdministrator"));assertEquals(role,f.store.profile(target).get("delegatedRoleName"));assertTrue(f.store.verifyAudit());}
 @Test void newInitiatorSessionCannotReuseAnOlderPendingPermit(){byte[] body=IdentityProtocol.accountRecoveryApproval(f.second.account());Map<String,Object> p=f.request(f.owner,owner,"account.sensitive_recovery.approve",body);f.approve(f.second,second,p,body);String n=IdentityProtocol.nonce();var session=f.store.login(f.owner.account(),f.owner.deviceId(),f.clock.millis(),n,IdentityProtocol.sign(f.owner.device().getPrivate(),IdentityProtocol.login(f.store.audience(),f.owner.account(),f.owner.deviceId(),f.clock.millis(),n)));var fresh=new CriticalApprovalTest.Person(f.owner.root(),f.owner.device(),f.owner.recovery(),f.owner.app(),session.accountId(),session.deviceId(),session.generation());Capability current=f.admin(fresh);assertThrows(IdentityException.class,()->f.consume(fresh,current,p,body));assertThrows(IdentityException.class,()->inspect(fresh,current,(String)p.get("requestId"),IdentityProtocol.nonce()));assertTrue(f.store.verifyAudit());}
 @Test void revokeCannotRemoveEitherInitiatorOrIndependentApprover(){byte[] body=IdentityProtocol.administratorRevocation(f.second.account());Map<String,Object> p=f.request(f.owner,owner,"administrator.revoke",body);f.approve(f.second,second,p,body);Map<String,Object> first=p;assertThrows(IdentityException.class,()->revoke(f.owner,owner,first,f.second.account()));Map<String,Object> q=f.request(f.second,second,"administrator.revoke",body);f.approve(f.owner,owner,q,body);assertThrows(IdentityException.class,()->revoke(f.second,second,q,f.second.account()));assertTrue(f.store.isActive(second));assertTrue(f.store.verifyAudit());}
}
